head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods17000";

// TODO Stage2: 세션 키 실환경 확인(회신 11항) — session.user.usrId

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods17000.onpageload' });
    }
};

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods17000' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldods17000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name detail
 * @description detail 처리
 * @param {String} ipt_integUsrId ipt_integUsrId
 * @param {String} ipt_usrStatId ipt_usrStatId
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} ipt_chrgTpCd ipt_chrgTpCd
 * @param {String} ipt_disclsBzChrgAssgnDd ipt_disclsBzChrgAssgnDd
 * @param {*} ipt_seq ipt_seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.detail = async function (ipt_integUsrId, ipt_usrStatId, ipt_isurCd, ipt_chrgTpCd, ipt_disclsBzChrgAssgnDd, ipt_seq) {
    if (ipt_integUsrId === (String(($c.session.getUserInfo("usrId")) == null ? '' : ($c.session.getUserInfo("usrId"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("usrId")) == null ? '' : ($c.session.getUserInfo("usrId"))))) {
        await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /account/mypage.do?method=memberInfoForm). 전환 대상 화면이 확정되면 연결됩니다.');
        return;
    }
    $('#ipt_integUsrId', $('#searchForm')).val(ipt_integUsrId);
    $('#ipt_usrStatId', $('#searchForm')).val("");
    $('#ipt_isurCd', $('#searchForm')).val(ipt_isurCd);
    $('#ipt_chrgTpCd', $('#searchForm')).val(ipt_chrgTpCd);
    $('#ipt_disclsBzChrgAssgnDd', $('#searchForm')).val(ipt_disclsBzChrgAssgnDd);
    $('#ipt_seq', $('#searchForm')).val(ipt_seq);
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17010/jldods17010.xml");
    $('#ipt_method', $('#searchForm')).val("readUserDetail");
    $('#searchForm').submit();
};
